import { createSignal } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  const value = count();
  return <p>{value}</p>;
}

import { createSignal } from "solid-js";
export function TodoLabel() {
  const [title] = createSignal("buy milk");
  const prefix = "Todo: ";
  const text = prefix + title();
  return <label>{text}</label>;
}

import { createSignal } from "solid-js";
export function TodoStatus() {
  const [done] = createSignal(false);
  const label = done() ? "done" : "open";
  return <span>{label}</span>;
}

import { createSignal, createEffect } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  createEffect(() => count());
  return <p>{count()}</p>;
}

import { createMemo } from "solid-js";
import { render } from "@solidjs/web";
function App() {
  const count = createMemo(async () => 1);
  return <p>{count()}</p>;
}
render(App, document.body);

import { createMemo } from "solid-js";
function TodoCount(props: { count: number }) {
  return <p>{props.count}</p>;
}
export function App() {
  const count = createMemo(async () => 1);
  return <TodoCount count={count()} />;
}

import { createSignal } from "solid-js";
export function Counter() {
  const [count] = createSignal(0);
  const label = <p>{count()}</p>;
  return <div>{label}</div>;
}

import { createSignal, createMemo } from "solid-js";
export function Counter() {
  const [count, setCount] = createSignal(0);
  const twice = createMemo(() => {
    setCount(1);
    return count() * 2;
  });
  return <p>{twice()}</p>;
}

import { createSignal } from "solid-js";
export function Counter() {
  return <p>{createSignal(1)[0]()}</p>;
}

import { createContext, useContext } from "solid-js";
import { render } from "@solidjs/web";
const Identity = createContext<string>();
function App() {
  const name = useContext(Identity);
  return <p>{name}</p>;
}
render(App, document.body);
